package software.amazon.event.ruler;

import org.junit.jupiter.api.Test;

import java.lang.reflect.Constructor;
import java.lang.reflect.Field;
import java.lang.reflect.Method;

import static org.junit.jupiter.api.Assertions.*;

class RangeLessThanOrEqualToTest {

    @Test
    void testLessThanOrEqualToReturnsRangeWithMinBottomAndComputedTop() throws Exception {
        String value = "123.45";

        // call the focal method
        Range r = Range.lessThanOrEqualTo(value);

        // access private static method stringToComparableBytes via reflection to compute expected top bytes
        Method stringToComparableBytes = Range.class.getDeclaredMethod("stringToComparableBytes", String.class);
        stringToComparableBytes.setAccessible(true);
        byte[] expectedTop = (byte[]) stringToComparableBytes.invoke(null, value);

        // access private static field MIN_RANGE_BYTES via reflection to get expected bottom bytes
        Field minField = Range.class.getDeclaredField("MIN_RANGE_BYTES");
        minField.setAccessible(true);
        byte[] expectedMin = (byte[]) minField.get(null);

        // verify the produced range
        assertNotNull(r, "Range should not be null");
        assertArrayEquals(expectedMin, r.bottom, "bottom should be MIN_RANGE_BYTES");
        assertArrayEquals(expectedTop, r.top, "top should equal stringToComparableBytes(value)");
        assertFalse(r.openBottom, "openBottom should be false");
        assertFalse(r.openTop, "openTop should be false");
        assertFalse(r.isCIDR, "isCIDR should be false");
    }

    @Test
    void testPrivateCopyConstructorClonesArraysAndPreservesFlags() throws Exception {
        String value = "-7.89e2";

        // original range via focal method
        Range original = Range.lessThanOrEqualTo(value);

        // get private copy constructor Range(Range) and invoke it via reflection
        Constructor<Range> copyCtor = Range.class.getDeclaredConstructor(Range.class);
        copyCtor.setAccessible(true);
        Range copy = copyCtor.newInstance(original);

        // verify fields are equal in content
        assertArrayEquals(original.bottom, copy.bottom, "copied bottom bytes should equal original");
        assertArrayEquals(original.top, copy.top, "copied top bytes should equal original");
        assertEquals(original.openBottom, copy.openBottom, "openBottom flag should be preserved");
        assertEquals(original.openTop, copy.openTop, "openTop flag should be preserved");
        assertEquals(original.isCIDR, copy.isCIDR, "isCIDR flag should be preserved");

        // verify arrays were cloned (different instances)
        assertNotSame(original.bottom, copy.bottom, "bottom arrays should be cloned (different instances)");
        assertNotSame(original.top, copy.top, "top arrays should be cloned (different instances)");
    }
}

